/**
 * PetRescue — lightweight PWA entry point.
 *
 * The product shell intentionally has no runtime dependency on optional
 * workspace UI packages, so the first user flow can be developed and tested
 * independently of the legacy design-system and WASM engine.
 */

import { AppShell } from './app-shell.js';

const target = document.getElementById('app');

if (!target) {
  throw new Error('PetRescue could not start: #app element was not found.');
}

const app = new AppShell();
app.mount(target);

if ('serviceWorker' in navigator && import.meta.env.PROD) {
  navigator.serviceWorker
    .register(`${import.meta.env.BASE_URL}sw.js`)
    .catch((error: unknown) => console.error('Service worker registration failed:', error));
}

if (import.meta.hot) {
  import.meta.hot.dispose(() => app.unmount());
}
